// Job data from the site localhost:7777 (one flat record for the whole run)
const b = $input.first().json.body || $input.first().json;
if (!b.jobId) throw new Error('Webhook called without jobId — it must be started from the site http://localhost:7777');
const audioDir = (b.audioDir || 'C:/medminute/audio').replace(/\\/g, '/');
return [{ json: {
  jobId: b.jobId,
  mode: b.mode || 'online',
  fileName: b.fileName || 'audio',
  ext: b.ext || 'm4a',
  inputPath: (b.inputPath || `${audioDir}/${b.jobId}_input.${b.ext || 'm4a'}`).replace(/\\/g, '/'),
  audioDir,
  reportsDir: (b.reportsDir || 'C:/medminute/reports').replace(/\\/g, '/'),
  submittedAt: b.submittedAt || new Date().toISOString(),
  callbackUrl: b.callbackUrl || `http://localhost:7777/api/jobs/${b.jobId}`,
} }];

// Speaker labels across the whole recording: A, B, C… → Participant 1, 2, 3 (in order of appearance)
const r = $input.first().json || {};
const segs = Array.isArray(r.segments) ? r.segments : [];
const map = new Map();
const who = (raw) => {
  raw = String(raw ?? '?').trim() || '?';
  if (!map.has(raw)) map.set(raw, `Participant ${map.size + 1}`);
  return map.get(raw);
};
const out = segs
  .map(s => ({ t: Number(s.start) || 0, end: Number(s.end) || 0, spk: who(s.speaker), text: String(s.text || '').trim() }))
  .filter(s => s.text);
return [{ json: { speakers: [...map.values()], segments: out } }];

// ===== SLICING: two versions (15s and 5s), cut in pauses =====
// Two slicings: 15s (better Romanian) and 5s (loses nothing, keeps the language). prompt: 'ro' | 'neutral' | 'none'
// NOTE: the 'ro' prompt is a Whisper priming prompt, not an instruction. Its Russian fragment ('Русский — кириллицей.')
// is intentional: it primes the model to write Russian speech in Cyrillic. Do not translate it.
const CONFIGS = [
  { name: '15s', MIN: 10,  TARGET: 15, MAX: 19,  OVERLAP: 0.5, prompt: 'ro' },
  { name: '5s',  MIN: 3.5, TARGET: 5,  MAX: 6.5, OVERLAP: 0.5, prompt: 'ro' },
];
const MERGE_FROM = ['15s', '5s'];
const PROMPTS = {
  ro: 'Transcrie exact ce se aude, în limba vorbită, fără traducere. Română — cu litere latine și diacritice (ă, â, î, ș, ț). Русский — кириллицей. English — in English. Ședință medicală MedMinute: noradrenalină, dobutamină, creatinină, uree, meropenem, amikacină, fluconazol, hidronefroză, nefrostomă, stent, BIPAP, ECO, EKG, hemoglobină, lactat.',
  neutral: 'Medical team meeting. Speakers switch between Russian, Romanian and English, often inside one sentence. Write every word exactly in the language it was spoken: Russian in Cyrillic, Romanian in Latin letters with diacritics, English in English. Never translate.',
  none: '.',
};
const PAD = 0.6; // silence at the end of each segment
// ==========================================================================

const log = String($json.stderr || '') + '\n' + String($json.stdout || '');
const hms = (m) => (+m[1]) * 3600 + (+m[2]) * 60 + parseFloat(m[3]);
let total = null;
const dm = log.match(/Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/);
if (dm) total = hms(dm);
else {
  // Recording from the in-browser recorder: Chrome writes WebM as a stream, there is no duration in the header (Duration: N/A).
  // Take the last ffmpeg progress line — time=00:00:17.75.
  const ts = [...log.matchAll(/time=\s*(\d+):(\d+):(\d+(?:\.\d+)?)/g)];
  if (ts.length) total = hms(ts[ts.length - 1]);
}
if (!total || !isFinite(total) || total <= 0) {
  throw new Error('ffmpeg did not return a duration. Log:\n' + log.slice(0, 800));
}
const pauses = [...log.matchAll(/silence_end:\s*([\d.]+)\s*\|\s*silence_duration:\s*([\d.]+)/g)]
  .map(m => ({ mid: +m[1] - (+m[2]) / 2, dur: +m[2] }))
  .filter(p => p.mid > 0 && p.mid < total);

const id = $('Job').first().json.jobId;
const ext = $('Job').first().json.ext;
const input = `C:/medminute/audio/${id}_input.${ext}`;
const out = [];

for (const c of CONFIGS) {
  const cuts = []; let last = 0, forced = 0;
  while (total - last > c.MAX) {
    const cands = pauses.filter(p => p.mid >= last + c.MIN && p.mid <= last + c.MAX);
    let cut;
    if (cands.length) {
      cands.sort((a, b) => (b.dur - Math.abs(b.mid - last - c.TARGET) * 0.1) - (a.dur - Math.abs(a.mid - last - c.TARGET) * 0.1));
      cut = cands[0].mid;
    } else { cut = last + c.TARGET; forced++; }
    cuts.push(+cut.toFixed(2)); last = cut;
  }
  const b = [0, ...cuts, +total.toFixed(2)];
  for (let i = 0; i < b.length - 1; i++) {
    const cs = Math.max(0, b[i] - c.OVERLAP), ce = Math.min(total, b[i + 1] + c.OVERLAP);
    const file = `C:/medminute/audio/${id}_${c.name}__seg_${String(i).padStart(4, '0')}.mp3`;
    out.push({ json: {
      config: c.name, prompt: PROMPTS[c.prompt] ?? '.', mergeFrom: MERGE_FROM, segIndex: i, start: b[i], forced, segCount: b.length - 1, total: +total.toFixed(1),
      cmd: `C:/medminute/ffmpeg/bin/ffmpeg.exe -y -loglevel error -ss ${cs.toFixed(2)} -t ${(ce - cs).toFixed(2)} -i "${input}" -af apad=pad_dur=${PAD} -ac 1 -ar 16000 -c:a libmp3lame -b:a 64k "${file}"`,
    } });
  }
}
return out;

const plan = new Map($('Slicing variants').all().map(i => [`${i.json.config}|${i.json.segIndex}`, i.json]));
const items = $input.all().map(it => {
  const name = it.binary?.data?.fileName || '';
  // jobId contains a hyphen and letters (20260927094732-95b9d4), so the ^\d+_ anchor did not match:
  // all segments fell into the '?' bucket, V15 and V5 came out empty, and the transcript was silently
  // built from diarize alone. The config name is taken as the piece before __seg_.
  const m = name.match(/_([^_]+)__seg_(\d+)\.mp3$/);
  const config = m ? m[1] : '?', idx = m ? parseInt(m[2], 10) : 0;
  const p = plan.get(`${config}|${idx}`) || {};
  return { json: { config, segIndex: idx, offsetSec: p.start ?? 0, prompt: p.prompt || '.' }, binary: it.binary };
});
items.sort((a, b) => a.json.config.localeCompare(b.json.config) || a.json.segIndex - b.json.segIndex);
// Fail loudly: without this check, empty V15 and V5 reached the merge step and the transcript
// was built from diarize alone — plausible-looking text, but completely different.
if (!items.length || items.every(i => i.json.config === '?')) {
  throw new Error('could not parse segment names: ' + (items[0]?.binary?.data?.fileName || 'no files'));
}
return items;

// Joins each slicing (15s, 5s) into a list of utterances with seconds; removes duplicates at the seams and junk
const segs = $('Number segments').all().map(i => i.json);
const normW = (w) => w.toLowerCase().replace(/ş/g, 'ș').replace(/ţ/g, 'ț').replace(/ё/g, 'е').replace(/[^\p{L}\p{N}]/gu, '');
const TERMS = ['noradrenalin', 'dobutamin', 'creatinin', 'uree', 'meropenem', 'amikacin', 'fluconazol', 'hidronefroz', 'nefrostom', 'bipap', 'hemoglobin', 'lactat'];
// The Russian phrases below are intentional: they match Whisper hallucinations in Russian (YouTube-style
// endings on silence) and the regurgitated priming prompt. Do not translate them.
const junk = (t) => {
  if (/(subtitr|vizionare|субтитр|продолжение следует|спасибо за просмотр|thanks for watching|amara\.org|transcrie exact|кириллицей|ședință medicală medminute|never translate|medical team meeting)/i.test(t)) return true;
  const low = t.toLowerCase();
  return TERMS.filter(x => low.includes(x)).length >= 3;
};
const byCfg = {};
$input.all().forEach((it, i) => {
  const s = segs[i]; if (!s) return;
  (byCfg[s.config] ||= []).push({ t: s.offsetSec, idx: s.segIndex, text: String(it.json.text || '').replace(/\s+/g, ' ').trim() });
});
const variants = {};
for (const [cfg, arr] of Object.entries(byCfg)) {
  arr.sort((a, b) => a.idx - b.idx);
  let prev = []; const out = [];
  for (const x of arr) {
    if (!x.text || junk(x.text)) continue;
    let w = x.text.split(' ');
    for (let k = Math.min(8, prev.length, w.length); k >= 1; k--) {
      if (prev.slice(-k).map(normW).join(' ') === w.slice(0, k).map(normW).join(' ')) { w = w.slice(k); break; }
    }
    if (!w.length) continue;
    prev = w; out.push({ t: x.t, text: w.join(' ') });
  }
  variants[cfg] = out;
}
return [{ json: { variants } }];

// Verbatim transcript — straight from recognition, without a model rewriting it.
// Previously gpt-4.1 merged 5-minute windows: it saw V5, V15 and the speaker labels at once
// and stitched them as it saw fit — edited words, inserted text from diarize,
// paraphrased in places. Exactly this distortion reached the minutes and all the tables.
// Now the text is taken as recognised (V5 — 3-5 second pieces, nothing gets swallowed),
// V15 is not combined with it, and the speaker is assigned by timecode. The model does not touch the text.
const V = $('Join versions').first().json.variants || {};
const D = $('Speakers (format)').first().json.segments || [];
const base = V['5s'] || [];
if (!base.length) {
  throw new Error('recognition did not produce the V5 version — nothing to build the transcript from');
}
const fmt = (s) => { s = Math.max(0, Math.round(+s || 0)); const p = n => String(n).padStart(2, '0');
  const h = Math.floor(s / 3600); return (h ? p(h) + ':' : '') + p(Math.floor((s % 3600) / 60)) + ':' + p(s % 60); };

// Who was speaking at this moment: the one whose labelled utterance overlaps the start of the piece,
// otherwise the nearest in time. The diarize text is not used — only the label and the time.
const who = (t) => {
  const hit = D.find(x => t >= x.t && t < (x.end || x.t))
    || D.reduce((a, x) => (!a || Math.abs(x.t - t) < Math.abs(a.t - t) ? x : a), null);
  return hit ? hit.spk : 'Participant 1';
};

// Dialogue: consecutive pieces from one person form one utterance, but no longer than 20 seconds,
// otherwise a labelling failure would glue the whole recording into one line.
const BLOCK = 20;
const out = [];
for (const x of base) {
  const said = String(x.text || '').trim();
  if (!said) continue;
  const spk = who(x.t);
  const last = out[out.length - 1];
  if (last && last.spk === spk && x.t - last.t < BLOCK) last.text += ' ' + said;
  else out.push({ t: x.t, spk, text: said });
}
const text = out.map(x => `[${fmt(x.t)}] ${x.spk}: ${x.text}`).join('\n');
return [{ json: { text, speakers: $('Speakers (format)').first().json.speakers } }];

// Three minutes languages + people directory + original recording with language tags
const tz = 'Europe/Chisinau';
const sub = $('Job').first().json.submittedAt;
const meetingDate = (sub ? DateTime.fromISO(sub) : $now).setZone(tz).toFormat('dd.LL.yyyy');
const src = $json;
const text = src.text;

// The utterance language is detected by script: Cyrillic → Russian, diacritics/function words → Romanian.
const RO_WORDS = /\b(este|sunt|care|pentru|nu|si|cu|la|de|in|am|are|face|foarte|bine|pacient|pacienta|tensiune|doamna|domnul|acum|dupa|mai|dar|ca|sa|se|un|o)\b/i;
function langOf(line) {
  const t = line.replace(/^\[[\d:]+\]\s*/, '').replace(/^[^:]{0,60}:\s*/, '');
  if (/[\u0430-\u044f\u0451]/i.test(t)) return 'ru';
  if (/[\u0103\u00e2\u00ee\u0219\u021b\u0102\u00c2\u00ce\u0218\u021a]/.test(t)) return 'ro';
  if (RO_WORDS.test(t)) return 'ro';
  return 'en';
}
const LNAME = { ru: 'Russian', ro: 'Romanian', en: 'English' };
const lines = String(text || '').split('\n').filter((l) => l.trim());
const counts = { ru: 0, ro: 0, en: 0 };
const marked = lines.map((l) => { const g = langOf(l); counts[g]++; return `\`${g.toUpperCase()}\` ${l}`; });
const totalLines = lines.length || 1;
const langStats = Object.entries(counts).filter(([, c]) => c)
  .sort((a, b) => b[1] - a[1])
  .map(([g, c]) => ({ lang: g, name: LNAME[g], lines: c, percent: Math.round((c / totalLines) * 100) }));
const langLine = langStats.map((s) => `${s.name} — ${s.percent}% (${s.lines} ${s.lines === 1 ? 'utterance' : 'utterances'})`).join(', ');

// The people directory is built in "Transcript with names" — one for all minutes branches.
const roster = src.roster || '';

const original = marked.join('\n');
// Section headings in the minutes language. Without this the model translated the text but copied the headings
// from the response schema as they were — and an untranslated heading stayed in the other-language minutes.
// The schema headings are English; the 'ru' map below is intentionally in Russian: it is the Russian minutes output.
const HEADS = {
  ru: 'Letter → Письмо; Subject → Тема; Participants → Участники; Agenda → Повестка; '
    + 'Objectives → Цели; Decisions → Решения; Action items → Действия; Minutes of the meeting → Протокол встречи; '
    + 'Date → Дата; Open questions → Открытые вопросы; Next meeting → Следующая встреча; Absentees → Отсутствовали; Agenda item → Пункт повестки; Key takeaways → Главные выводы; Materials → Материалы',
  ro: 'Letter → Scrisoare; Subject → Subiect; Participants → Participanți; Agenda → Ordinea de zi; '
    + 'Objectives → Obiective; Decisions → Decizii; Action items → Acțiuni; Minutes of the meeting → Proces-verbal al ședinței; '
    + 'Date → Data; Open questions → Întrebări deschise; Next meeting → Următoarea ședință; Absentees → Absenți; Agenda item → Punct pe ordinea de zi; Key takeaways → Concluzii principale; Materials → Materiale',
  en: 'they are already in English, write them as in the schema',
};

const common = { meetingDate, text, roster, original, langStats, langLine };
return [
  { json: { ...common, lang: 'ru', langName: 'Russian', heads: HEADS.ru } },
  { json: { ...common, lang: 'ro', langName: 'Romanian (limba română)', heads: HEADS.ro } },
  { json: { ...common, lang: 'en', langName: 'English', heads: HEADS.en } },
];

// Reports RU / RO / EN + transcript + source versions. The files are written by the site.
const tz = 'Europe/Chisinau';
const form = $('Job').first();
const rec = form.json.submittedAt ? DateTime.fromISO(form.json.submittedAt).setZone(tz) : $now.setZone(tz);
const created = $now.setZone(tz);
let src = (form.json.fileName || 'audio').replace(/\.[^.]+$/, '').replace(/[^\p{L}\p{N}_-]+/gu, '_');
if (!/^medminute/i.test(src)) src = 'MedMinute_' + src;
const base = `${src}__recorded-${rec.toFormat('yyyy-LL-dd_HH-mm')}__report-${created.toFormat('yyyy-LL-dd_HH-mm')}`;
const head = (title) => [`# ${title}`, '', `File: ${form.json.fileName || '—'}`,
  `Recording uploaded: ${rec.toFormat('dd.LL.yyyy HH:mm')}`, `Report created: ${created.toFormat('dd.LL.yyyy HH:mm')}`, '', '---', ''].join('\n');

const langs = $('Three languages').all().map(i => i.json.lang);

// The original recording is appended to the end of every report: you can see that part of the speech was
// in Russian, part in Romanian, part in English — and compare it with the minutes.
const L = $('Three languages').first().json;
const tail = ['', '---', '', '## Original recording (as spoken)', '',
  `Languages in the recording: ${L.langLine || '—'}.`,
  'The tag at the start of a line is the utterance language. The text was not translated or edited.', '',
  '```', L.original || '', '```', ''].join('\n');
const out = $input.all().map((it, i) => {
  const lang = langs[i] || `lang${i}`;
  const content = String(it.json.choices?.[0]?.message?.content ?? '').replace(/^\`\`\`(?:markdown|md)?\s*|\s*\`\`\`$/g, '').trim();
  if (!content) throw new Error(`Empty model response for language ${lang}`);
  return { json: { lang, fileName: `${base}.${lang}.md`, content: content + '\n' + tail } };
});

// final transcript (assembled, with speakers, in the original languages)
const fin = $('Transcript with names').first().json;
out.push({ json: { lang: 'transcript', fileName: `${base}.transcript.md`,
  content: head('Meeting transcript (original languages, with speakers)')
    + `Participants (by voice): ${(fin.speakers || []).join(', ') || '—'}\n\n` + fin.text + '\n' } });

// source recognitions — for manual checking of disputed places
const fmt = (s) => { s = Math.max(0, Math.round(+s || 0)); const p = n => String(n).padStart(2, '0');
  const h = Math.floor(s / 3600); return (h ? p(h) + ':' : '') + p(Math.floor((s % 3600) / 60)) + ':' + p(s % 60); };
const V = $('Join versions').first().json.variants || {};
const D = $('Speakers (format)').first().json.segments || [];
out.push({ json: { lang: 'sources', fileName: `${base}.sources.md`, content: [head('Source recognitions (no AI edits)'),
  '## Speaker labels (diarize)', '', ...D.map(x => `[${fmt(x.t)}] ${x.spk}: ${x.text}`), '',
  '## Version 15s', '', ...(V['15s'] || []).map(x => `[${fmt(x.t)}] ${x.text}`), '',
  '## Version 5s', '', ...(V['5s'] || []).map(x => `[${fmt(x.t)}] ${x.text}`), ''].join('\n') } });
return out;

const tz = 'Europe/Chisinau';
const form = $('Job').first();
const sub = form.json.submittedAt;
const meetingDate = (sub ? DateTime.fromISO(sub) : $now).setZone(tz).toFormat('dd.LL.yyyy');
const added = $now.setZone(tz).toFormat('dd.LL.yyyy HH:mm');
const file = form.json.fileName || '—';
const raw = String($json.choices?.[0]?.message?.content || '{}').replace(/^```\w*\s*|\s*```$/g, '');
let data; try { data = JSON.parse(raw); } catch (e) { throw new Error('The model returned invalid JSON: ' + raw.slice(0, 500)); }
const title = data.meeting_title || 'Meeting';
const rows = (data.decisions || []).map((x, i) => ({ json: {
  'Meeting date': meetingDate, 'Meeting': title, '#': i + 1, 'Patient': x.patient || '',
  'Decision': x.decision || '', 'Proposed by': x.proposed_by || 'not specified', 'Approved by': x.approved_by || 'not specified',
  'Timecode': x.timecode || '', 'Context': x.context || '',
  'Recording file': file, 'Added': added,
} }));
return [{ json: { rows: rows.map(r => r.json ?? r) } }];

const tz = 'Europe/Chisinau';
const form = $('Job').first();
const sub = form.json.submittedAt;
const meetingDate = (sub ? DateTime.fromISO(sub) : $now).setZone(tz).toFormat('dd.LL.yyyy');
const added = $now.setZone(tz).toFormat('dd.LL.yyyy HH:mm');
const file = form.json.fileName || '—';
const raw = String($json.choices?.[0]?.message?.content || '{}').replace(/^```\w*\s*|\s*```$/g, '');
let data; try { data = JSON.parse(raw); } catch (e) { throw new Error('The model returned invalid JSON: ' + raw.slice(0, 500)); }
const title = data.meeting_title || 'Meeting';
const rows = (data.action_items || []).map((x, i) => ({ json: {
  'Meeting date': meetingDate, 'Meeting': title, '#': i + 1, 'Patient': x.patient || '',
  'Task': x.task || '', 'Owner': x.owner || 'not specified', 'Deadline': x.deadline || 'not specified',
  'Timecode': x.timecode || '', 'Status': 'New',
  'Recording file': file, 'Added': added,
} }));
return [{ json: { rows: rows.map(r => r.json ?? r) } }];

// Minutes in 3 languages for the site
const tz = 'Europe/Chisinau';
const j = $('Job').first().json;
const meetingDate = DateTime.fromISO(j.submittedAt).setZone(tz).toFormat('dd.LL.yyyy');
const clean = (s) => String(s || '').replace(/^\`\`\`(?:markdown|md)?\s*|\s*\`\`\`$/g, '').trim();
const langs = $('Three languages').all().map(i => i.json.lang);
const mom = {};
$input.all().forEach((it, i) => { mom[langs[i]] = clean(it.json.choices?.[0]?.message?.content); });
// The meeting title is taken from the English minutes (falls back to Russian).
const m = (mom.en || mom.ru || '').match(/MoM:\s*(.+?)\s*\[/);
const fin = $('Transcript with names').first().json;
const L = $('Three languages').first().json;
return [{ json: {
  title: m ? m[1].trim() : 'Meeting',
  meetingDate,
  participants: fin.speakers || [],
  fileName: j.fileName,
  ru: mom.ru || '', ro: mom.ro || '', en: mom.en || '',
  original: L.original || '', langStats: L.langStats || [], langLine: L.langLine || '',
  mentioned: fin.mentioned || [],
} }];

// One row per prescription; a patient without prescriptions also gets a row (so they are not lost)
const tz = 'Europe/Chisinau';
const form = $('Job').first();
const sub = form.json.submittedAt;
const meetingDate = (sub ? DateTime.fromISO(sub) : $now).setZone(tz).toFormat('dd.LL.yyyy');
const added = $now.setZone(tz).toFormat('dd.LL.yyyy HH:mm');
const file = form.json.fileName || '—';
const raw = String($json.choices?.[0]?.message?.content || '{}').replace(/^```\w*\s*|\s*```$/g, '');
let data; try { data = JSON.parse(raw); } catch (e) { throw new Error('The model returned invalid JSON: ' + raw.slice(0, 500)); }
const rows = [];
for (const p of data.patients || []) {
  const base = {
    'Meeting date': meetingDate,
    'Patient': p.patient || 'not specified',
    'Bed / ward': p.bed || '',
    'Condition (as stated)': p.status || '',
  };
  const meds = (p.medications || []).length ? p.medications : [null];
  for (const m of meds) {
    rows.push({ json: { ...base,
      'Drug (as heard)': m ? (m.drug || '') : '— no prescriptions mentioned —',
      'Drug (probable)': m ? (m.drug_normalized || '') : '',
      'Dose': m ? (m.dose || 'not specified') : '',
      'Route': m ? (m.route || '') : '',
      'Action': m ? (m.action || '') : '',
      'Prescribed / reported by': m ? (m.by || 'not specified') : '',
      'Timecode': m ? (m.timecode || '') : (p.first_mention || ''),
      'Quote': m ? (m.quote || '') : '',
      'Confidence': m ? (m.confidence || '') : '',
      'Note': p.note || '',
      'Checked by physician': '',
      'Recording file': file,
      'Added': added,
    } });
  }
}
return [{ json: { rows: rows.map(r => r.json ?? r) } }];

// Puts names into the transcript: "Participant 2:" → "John Smith, cardiologist (Participant 2):"
// medium confidence is marked "(?)", low is not substituted
const fin = $('Final transcript').first().json;
const raw = String($json.choices?.[0]?.message?.content || '{}').replace(/^```\w*\s*|\s*```$/g, '');
let data = {}; try { data = JSON.parse(raw); } catch (e) { data = {}; }
const map = {};
for (const s of data.speakers || []) {
  const conf = String(s.confidence || '').toLowerCase();
  // The Cyrillic prefixes are a fallback in case the model answers the confidence in Russian.
  if (!s.speaker || !s.name || conf.startsWith('low') || conf.startsWith('низ')) continue;
  const q = conf.startsWith('med') || conf.startsWith('сред') ? ' (?)' : '';
  const role = s.role ? `, ${s.role}` : '';
  map[s.speaker.trim()] = `${s.name.trim()}${q}${role} (${s.speaker.trim()})`;
}
const esc = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
let text = String(fin.text || '');
for (const [spk, label] of Object.entries(map)) {
  text = text.replace(new RegExp(`(\\]\\s*)${esc(spk)}(?=\\s*:)`, 'g'), `$1${label}`);
}
const speakers = (fin.speakers || []).map(s => map[s] || s);
const evidence = data.speakers || [];
const mentioned = data.mentioned || [];

// People directory: who spoke and who was talked about. It goes into the prompts of all three branches,
// so that decisions, tasks and prescriptions are linked to a specific patient rather than "not specified".
const spkList = evidence.filter((s) => s.name)
  .map((s) => `- ${s.name}${s.role ? `, ${s.role}` : ''} — is ${s.speaker}` + (s.evidence ? ` (${s.evidence})` : ''));
const menList = mentioned
  .map((m) => `- ${m.name || 'name not mentioned'}${m.kind ? ` — ${m.kind}` : ''}`
    + `${m.bed ? `, bed/ward ${m.bed}` : ''}${m.about ? `: ${m.about}` : ''}`
    + (m.evidence ? ` (${m.evidence})` : ''));
// The Cyrillic alternatives are a fallback in case the model answers the kind in Russian.
const patients = mentioned.filter((m) => !m.kind || /patient|pacient|пациент|больн/i.test(m.kind))
  .map((m) => [m.name, m.bed && `bed/ward ${m.bed}`].filter(Boolean).join(', '))
  .filter(Boolean);
let roster = '';
if (spkList.length || menList.length) {
  roster = '\n\nPEOPLE DIRECTORY (established in advance, use exactly these names):\n'
    + (spkList.length ? 'Speakers at the meeting:\n' + spkList.join('\n') + '\n' : '')
    + (menList.length ? 'People who were talked about (mostly patients):\n' + menList.join('\n') + '\n' : '')
    + 'In the minutes call these people by name. Keep "Participant N" only where there is no name '
    + 'either in the directory or in the transcript. In the "Patients and prescriptions" section make the heading of each '
    + 'block the patient name and bed, not "patient not named".\n';
}
return [{ json: { text, speakers, nameMap: map, evidence, mentioned, roster, patients } }];

// Source recognitions — to the site, "Source versions" tab
const fmt = (s) => { s = Math.max(0, Math.round(+s || 0)); const p = n => String(n).padStart(2, '0');
  const h = Math.floor(s / 3600); return (h ? p(h) + ':' : '') + p(Math.floor((s % 3600) / 60)) + ':' + p(s % 60); };
const V = $('Join versions').first().json.variants || {};
const D = $('Speakers (format)').first().json.segments || [];
return [{ json: {
  diar: D.map(x => `[${fmt(x.t)}] ${x.spk}: ${x.text}`).join('\n'),
  v15: (V['15s'] || []).map(x => `[${fmt(x.t)}] ${x.text}`).join('\n'),
  v5: (V['5s'] || []).map(x => `[${fmt(x.t)}] ${x.text}`).join('\n'),
} }];
